import * as T from './vendor/three.module.js';
import {citizenModel} from './chapter-two-models.js';
import {beastModel} from './chapter-two-wildlife.js';
import {dragonModel} from './chapter-two-atmosphere.js';
export const C4_STATS={drowned:{hp:280,damage:29,level:23},hag:{hp:250,damage:27,level:24},harpy:{hp:260,damage:26,level:24},whelp:{hp:320,damage:29,level:25},sentinel:{hp:430,damage:33,level:26},abbess:{hp:1500,damage:34,level:27},ashwing:{hp:2100,damage:37,level:29},werewolf:{hp:900,damage:36,level:24}};
export function chapterFourActor(parent,role,x,z,palette,id){
 const dragon=['whelp','ashwing'].includes(role),model=dragon?dragonModel():null,base=dragon?{g:model.g,update:dt=>model.animate(dt),cueAttack(){}}:role==='werewolf'?beastModel(parent,'werewolf',x,z):citizenModel(parent,x,z,{id,role:['hag','abbess'].includes(role)?'mage':'sword',woman:role==='hag'||role==='abbess',cloth:role==='drowned'?6:role==='abbess'?10:7,skin:1},palette);
 const g=base.g;if(dragon){parent.add(g);g.position.set(x,role==='ashwing'?1.05:.44,z);g.scale.setScalar(role==='ashwing'?.95:.4)}g.userData.dynamic=true;
 const metal=palette.material(8,0x6e8994),bone=palette.material(9,0xc0c7b4),glow=new T.MeshBasicMaterial({color:role==='abbess'?0xad6fff:0x8effca});const add=(geo,mat,x,y,z)=>{const m=new T.Mesh(geo,mat);m.position.set(x,y,z);g.add(m);return m};let wings=[],ward;
 if(role==='drowned'){g.traverse(n=>{if(n.isMesh)n.material=palette.material(6,0x4b7974)});for(const side of [-1,1])add(new T.SphereGeometry(.045,6,5),glow,side*.065,1.79,.19);add(new T.TorusGeometry(.24,.05,6,10),metal,0,.95,0).rotation.x=Math.PI/2;for(let i=0;i<4;i++)add(new T.ConeGeometry(.04,.45,5),palette.material(15,0x305947),Math.sin(i)*.23,1.55-i*.14,-.2)}
 if(role==='harpy'){for(const side of [-1,1]){const pivot=new T.Group();pivot.position.set(side*.25,1.4,0);g.add(pivot);for(let i=0;i<7;i++){const f=new T.Mesh(new T.ConeGeometry(.18,.95,5),palette.material(2,0x56707a));f.position.set(side*(.3+i*.16),.1-i*.08,-i*.06);f.rotation.z=-side*(.6+i*.07);pivot.add(f)}wings.push(pivot)}for(const side of [-1,1])add(new T.ConeGeometry(.1,.4,5),bone,side*.13,2.14,-.04)}
 if(['hag','abbess'].includes(role)){for(const side of [-1,1]){const horn=add(new T.ConeGeometry(.11,.55,6),bone,side*.19,2.16,0);horn.rotation.z=-side*.4}ward=add(new T.TorusGeometry(role==='abbess'?1.1:.7,.04,6,40),glow,0,.13,0);ward.rotation.x=Math.PI/2;if(role==='abbess'){g.scale.setScalar(1.25);add(new T.BoxGeometry(.42,.09,.1),metal,0,1.8,.18);for(let i=0;i<5;i++)add(new T.OctahedronGeometry(.055),glow,(i-2)*.11,2.27,0)}}
 if(role==='sentinel'){g.scale.setScalar(1.2);add(new T.SphereGeometry(.25,10,8),metal,0,1.9,0);for(const side of [-1,1])add(new T.ConeGeometry(.22,.5,6),bone,side*.36,1.5,0)}
 let age=0,attack=0;const update=base.update.bind(base),cue=base.cueAttack.bind(base);base.cueAttack=kind=>{attack=.75;cue(kind)};base.update=function(dt){age+=dt;attack=Math.max(0,attack-dt);if(dragon){model.animate(age*(this.flightLeft>0?1.5:1));if(!this.flightLeft)for(const [i,name] of ['dragon-wing-left','dragon-wing-right'].entries()){const w=g.getObjectByName(name);w.rotation.z=(i?1:-1)*(.35+Math.sin(age*1.1)*.04);w.rotation.x=0;}g.rotation.y=this.heading;const flight=this.flightLeft>0?Math.sin(Math.PI*(1-this.flightLeft/8)):0;g.position.y=(role==='ashwing'?1.05:.44)+Math.sin(age*2)*.025+flight*(role==='ashwing'?4.5:3);g.rotation.z=flight*Math.sin(age)*.1;const neck=g.getObjectByName('dragon-neck');neck.rotation.x=attack>0?-Math.sin((1-attack/.75)*Math.PI)*.5:0}else update(dt);if(role==='harpy'){g.position.y=.7+Math.sin(age*2)*.15;wings.forEach((w,i)=>w.rotation.z=Math.sin(age*4)*(i?.4:-.4))}if(ward){ward.rotation.z=age*2;ward.scale.setScalar(1+Math.sin(age*5)*.08);ward.visible=this.windup>0||role==='abbess'&&this.phase===2}};
 Object.assign(base,{id,role,chapterThree:true,chapterTwo:true,species:role,name:{drowned:'Утопец в цепях',hag:'Ведьма чёрных заводей',harpy:'Ночная гарпия',whelp:'Пепельный дракончик',sentinel:'Рыцарь пустой луны',abbess:'Слепая Матерь',ashwing:'Пеплокрыл',werewolf:'Оборотень вечной ночи'}[role],height:role==='ashwing'?3:role==='werewolf'?2.6:2,hp:C4_STATS[role].hp,maxHp:C4_STATS[role].hp,fixedLevel:C4_STATS[role].level,home:new T.Vector3(x,0,z),target:new T.Vector3(x,0,z),heading:0,generation:0,hit:false,aggro:null,timer:0,cooldown:1,windup:0,special:4,block:0,blockReady:4,flightLeft:0,flightReady:8,flightTarget:null,pending:'normal',phase:1,addsUsed:false});return base;
}
